<script lang="ts">
 import {searchPageHref} from '$lib/components/public/search-layout';import PublicLayout from '$lib/components/public/PublicLayout.svelte';import {publicHref,publicLabels,type PublicType} from '$lib/content/public';let {data}=$props();
